.cxsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2240;
    background: linear-gradient(160deg, #f4f3fb 0%, #eef0fa 100%);
    border-radius: 18px;
}

.cxsim-container * {
    box-sizing: border-box;
}

.cxsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2a1d6b 0%, #4534b8 52%, #6d4ad6 100%);
    color: #f6f4ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(42, 29, 107, 0.32);
}

.cxsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cxsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd9a8;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.cxsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6e1ff;
}

.cxsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a317a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cxsim-period-counter #currentDay,
.cxsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2a1d6b;
}

.cxsim-round-name {
    background: #e2def8;
    color: #4534b8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cxsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b5430f;
    background: #ffe5d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.cxsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cxsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e1ddf2;
    box-shadow: 0 4px 14px rgba(42, 29, 107, 0.07);
    border-top: 4px solid #6d4ad6;
}

.cxsim-card-nps { border-top-color: #2f6fb0; }
.cxsim-card-match { border-top-color: #14916e; }
.cxsim-card-repeat { border-top-color: #b07d16; }
.cxsim-card-supply { border-top-color: #c0392b; }

.cxsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c6a8f;
}

.cxsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a1d6b;
}

.cxsim-card-nps .cxsim-value { color: #2f6fb0; }
.cxsim-card-match .cxsim-value { color: #14916e; }
.cxsim-card-repeat .cxsim-value { color: #b07d16; }
.cxsim-card-supply .cxsim-value { color: #c0392b; }

.cxsim-sublabel {
    font-size: 0.76rem;
    color: #7c7a9c;
    line-height: 1.35;
}

.cxsim-supply-healthy.cxsim-card-supply { border-top-color: #14916e; }
.cxsim-supply-healthy.cxsim-card-supply .cxsim-value { color: #14916e; }

.cxsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: stretch;
    gap: 14px;
    margin-bottom: 18px;
}

.cxsim-budget-block {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 3px;
    background: #2a1d6b;
    color: #f0ecff;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cxsim-budget-block .cxsim-budget-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #b8aef0;
}

.cxsim-budget-block #budgetDisplay,
.cxsim-budget-block #sprintDisplay {
    font-size: 1.12rem;
    letter-spacing: 0.3px;
}

.cxsim-budget-over #budgetDisplay,
.cxsim-budget-over #sprintDisplay {
    color: #ff9d7a;
}

.cxsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6d4ad6;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(42, 29, 107, 0.05);
}

.cxsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cxsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2a1d6b;
    margin-bottom: 6px;
}

.cxsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34324f;
}

.cxsim-briefing-text strong { color: #14916e; }
.cxsim-briefing-text em { color: #b5430f; font-style: italic; }

.cxsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e1ddf2;
    box-shadow: 0 4px 14px rgba(42, 29, 107, 0.07);
}

.cxsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2a1d6b;
    border-bottom: 2px solid #ece9f9;
    padding-bottom: 8px;
}

.cxsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2e2c52;
    margin: 14px 0 6px;
}

.cxsim-container select,
.cxsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c8c1ea;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8f7fe;
    color: #1d2240;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cxsim-container select:focus,
.cxsim-container input[type="number"]:focus {
    outline: none;
    border-color: #6d4ad6;
    box-shadow: 0 0 0 3px rgba(109, 74, 214, 0.16);
}

.cxsim-container select option {
    background-color: #ffffff;
    color: #1d2240;
}

.cxsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6d4ad6;
}

.cxsim-range-readout,
.cxsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4534b8;
    margin-top: 4px;
}

.cxsim-range-readout span:last-child,
.cxsim-alloc-readout span#spendReadout,
.cxsim-alloc-readout span#sprintLiveReadout {
    color: #14916e;
    font-weight: 800;
}

.cxsim-hint {
    font-size: 0.8rem;
    color: #7c7a9c;
    margin-top: 4px;
    line-height: 1.4;
}

.cxsim-fix-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.cxsim-fix-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f4fd;
    border: 1px solid #e4dff7;
    border-radius: 9px;
    padding: 8px 12px;
}

.cxsim-fix-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2e2c52;
}

.cxsim-fix-row select {
    width: 110px;
    flex: 0 0 110px;
}

.cxsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cxsim-container .btn-primary {
    background: linear-gradient(135deg, #4534b8 0%, #6d4ad6 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(69, 52, 184, 0.30);
}

.cxsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.cxsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c8c1ea;
    color: #6c6a8f;
}

.cxsim-coach {
    background: #2a1d6b;
    color: #efebff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(42, 29, 107, 0.24);
}

.cxsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b8aef0;
    margin-bottom: 8px;
}

.cxsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cxsim-coach-body strong { color: #ffd9a8; }
.cxsim-coach-body em { color: #ffb38f; font-style: italic; }

.cxsim-history,
.cxsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e1ddf2;
    box-shadow: 0 4px 14px rgba(42, 29, 107, 0.07);
}

.cxsim-history h3,
.cxsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2a1d6b;
}

.cxsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2e2c52;
}

.cxsim-container table#usfHistoryTable th {
    background: #efecfa;
    color: #2a1d6b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0daf5;
}

.cxsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0edf9;
}

.cxsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9fe;
}

.cxsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cxsim-container {
        padding: 14px;
    }
    .cxsim-header h1 {
        font-size: 1.7rem;
    }
    .cxsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cxsim-value {
        font-size: 2rem;
    }
    .cxsim-clock {
        margin-left: 0;
    }
    .cxsim-period-counter {
        font-size: 0.88rem;
    }
    .cxsim-budget-bar {
        flex-direction: column;
        gap: 10px;
    }
    .cxsim-fix-row {
        flex-wrap: wrap;
    }
    .cxsim-fix-row select {
        width: 100%;
        flex: 1 1 100%;
    }
    .cxsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light) ===== */
.cxsim-completion { color:#282636; font-size:0.95rem; }
.cxsim-cm-head { text-align:center; margin-bottom:16px; }
.cxsim-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#6a4aa8; }
.cxsim-cm-score-max { font-size:1.2rem; font-weight:600; color:#a08cc8; }
.cxsim-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#1d1830; }
.cxsim-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.cxsim-cm-yes { background:rgba(106,74,168,0.14); color:#573b95; border:1px solid rgba(106,74,168,0.5); }
.cxsim-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.cxsim-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.cxsim-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.cxsim-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(29,24,48,0.06); border:1px solid rgba(29,24,48,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.cxsim-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#241f40; }
.cxsim-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#6c6a8f; text-transform:uppercase; letter-spacing:0.03em; }
.cxsim-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#1d1830; }
.cxsim-cm-insights { margin:0; padding-left:20px; }
.cxsim-cm-insights li { margin:4px 0; color:#332e4d; }

