(function() {
    'use strict';

    class ExperienceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Experience by Design`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (INR; budget held in lakh, displayed in crore) ----
            this.START_NPS = 31;        // was 46
            this.START_MATCH = 79;      // was 88
            this.START_REPEAT = 54;     // was 62
            this.START_SUPPLY = 40;     // top-pro churn doubled 4% -> 8%
            this.TARGET_NPS = 42;       // credible day-90 trajectory (back toward 46)
            this.TARGET_MATCH = 86;     // recover toward the prior 88%
            this.TARGET_REPEAT = 60;    // recover toward the prior 62%
            this.TARGET_SUPPLY = 60;    // top-pro retention healthy again
            this.BUDGET_CAP = 900;      // INR 9 crore, in lakh
            this.SPRINT_CAP = 6;        // engineering sprints

            // Fix menu — cost in lakh, sprints, side tags.
            this.FIXES = {
                booking:    { cost: 220, sprints: 2, id: `fixBookingInput` },
                onboarding: { cost: 180, sprints: 1, id: `fixOnboardingInput` },
                tracking:   { cost: 150, sprints: 1, id: `fixTrackingInput` },
                qa:         { cost: 250, sprints: 2, id: `fixQaInput` },
                payouts:    { cost: 120, sprints: 0, id: `fixPayoutsInput` },
                resolution: { cost: 140, sprints: 1, id: `fixResolutionInput` }
            };

            // Concept truths.
            this.TRUE_LENS = `twosided`;
            this.TRUE_LEAK = `payouts`;
            this.TRUE_MATCHING = `fairness`;
            this.TRUE_TRUST = `verification`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    nps: this.START_NPS,
                    match: this.START_MATCH,
                    repeat: this.START_REPEAT,
                    supply: this.START_SUPPLY,
                    budgetUsed: 0,
                    sprintsUsed: 0,
                    overspent: false,
                    targetMissed: false,
                    npsHistory: [this.START_NPS],
                    matchHistory: [this.START_MATCH],
                    repeatHistory: [this.START_REPEAT],
                    supplyHistory: [this.START_SUPPLY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / consumer-only mix — deliberately NOT the
                // textbook-correct play, so a click-through does not auto-win.
                state.decisions = {
                    lens: `consumer`,
                    leak: `bookingflow`,
                    rigor: 50,
                    fixBooking: 1,
                    fixOnboarding: 0,
                    fixTracking: 1,
                    fixQa: 0,
                    fixPayouts: 0,
                    fixResolution: 0,
                    matching: `speed`,
                    trust: `stackall`,
                    payfloor: 40,
                    friction: 2,
                    rebalance: `consumertrust`,
                    recovery: `quiet`,
                    pitch: `consumeronly`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lens = document.getElementById(`lensInput`);
                const leak = document.getElementById(`leakInput`);
                const rigor = document.getElementById(`rigorInput`);
                if (lens) decisions.lens = lens.value;
                if (leak) decisions.leak = leak.value;
                if (rigor) decisions.rigor = parseInt(rigor.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                let spend = 0, sprints = 0, count = 0, supplyFix = false;
                const map = {
                    fixBooking: `fixBookingInput`, fixOnboarding: `fixOnboardingInput`,
                    fixTracking: `fixTrackingInput`, fixQa: `fixQaInput`,
                    fixPayouts: `fixPayoutsInput`, fixResolution: `fixResolutionInput`
                };
                Object.keys(map).forEach((k) => {
                    const el = document.getElementById(map[k]);
                    if (el) decisions[k] = parseInt(el.value, 10);
                });
                if (decisions.fixBooking) { spend += this.FIXES.booking.cost; sprints += this.FIXES.booking.sprints; count++; }
                if (decisions.fixOnboarding) { spend += this.FIXES.onboarding.cost; sprints += this.FIXES.onboarding.sprints; count++; supplyFix = true; }
                if (decisions.fixTracking) { spend += this.FIXES.tracking.cost; sprints += this.FIXES.tracking.sprints; count++; }
                if (decisions.fixQa) { spend += this.FIXES.qa.cost; sprints += this.FIXES.qa.sprints; count++; }
                if (decisions.fixPayouts) { spend += this.FIXES.payouts.cost; sprints += this.FIXES.payouts.sprints; count++; supplyFix = true; }
                if (decisions.fixResolution) { spend += this.FIXES.resolution.cost; sprints += this.FIXES.resolution.sprints; count++; }
                if (count === 0) { warn(`warn_no_fix`); return false; }
                if (spend > this.BUDGET_CAP) { warn(`warn_over_budget`); return false; }
                if (sprints > this.SPRINT_CAP) { warn(`warn_over_sprints`); return false; }
                if (!supplyFix) { warn(`warn_no_supply`); return false; }
            } else if (round === 3) {
                const matching = document.getElementById(`matchingInput`);
                const trust = document.getElementById(`trustInput`);
                const payfloor = document.getElementById(`payfloorInput`);
                const friction = document.getElementById(`frictionInput`);
                if (matching) decisions.matching = matching.value;
                if (trust) decisions.trust = trust.value;
                if (payfloor) decisions.payfloor = parseInt(payfloor.value, 10);
                if (friction) decisions.friction = parseInt(friction.value, 10);
                if (!Number.isFinite(decisions.payfloor) || decisions.payfloor < 0 || decisions.payfloor > 100) {
                    warn(`warn_payfloor_range`); return false;
                }
                if (!Number.isFinite(decisions.friction) || decisions.friction < 0 || decisions.friction > 4) {
                    warn(`warn_friction_range`); return false;
                }
            } else if (round === 4) {
                const rebalance = document.getElementById(`rebalanceInput`);
                const recovery = document.getElementById(`recoveryInput`);
                const pitch = document.getElementById(`pitchInput`);
                const conviction = document.getElementById(`convictionInput`);
                if (rebalance) decisions.rebalance = rebalance.value;
                if (recovery) decisions.recovery = recovery.value;
                if (pitch) decisions.pitch = pitch.value;
                if (conviction) decisions.conviction = parseInt(conviction.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-KPI deltas this round.
            let npsD = 0, matchD = 0, repeatD = 0, supplyD = 0;
            let spend = 0, sprints = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose for whom value is leaking — two-sided beats consumer-only / competitor-chasing.
                switch (d.lens) {
                    case `twosided`: npsD += 3; supplyD += 5; repeatD += 2; coachKey = `coach_r1_twosided`; break;
                    case `consumer`: npsD += 3; supplyD -= 4; coachKey = `coach_r1_consumer`; break;
                    case `competitor`: npsD += 1; supplyD -= 3; coachKey = `coach_r1_competitor`; break;
                    case `individuals`: npsD -= 3; supplyD -= 5; coachKey = `coach_r1_individuals`; break;
                }
                // The leak that is uniquely GharSe's: T+7 payouts + slow resolution (supply-side).
                switch (d.leak) {
                    case `payouts`: supplyD += 6; matchD += 1; if (d.lens === `twosided`) coachKey = `coach_r1_sharp`; break;
                    case `bookingflow`: npsD += 2; supplyD -= 3; coachKey = (d.lens === `twosided`) ? coachKey : `coach_r1_consumer`; break;
                    case `pricewar`: supplyD += 2; matchD -= 1; coachKey = `coach_r1_pricewar`; break;
                    case `none`: npsD -= 4; supplyD -= 4; matchD -= 2; coachKey = `coach_r1_none`; break;
                }
                // Diagnostic rigor amplifies a correct read and exposes a lazy one.
                if (d.rigor >= 70) { npsD += 2; supplyD += 2; }
                else if (d.rigor <= 25) { npsD -= 3; supplyD -= 2; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.lens === `twosided` && d.leak === `payouts`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Costed touchpoint portfolio (must protect supply — validated upstream).
                if (d.fixBooking) { spend += this.FIXES.booking.cost; sprints += this.FIXES.booking.sprints; npsD += 6; repeatD += 4; }
                if (d.fixOnboarding) { spend += this.FIXES.onboarding.cost; sprints += this.FIXES.onboarding.sprints; matchD += 4; supplyD += 4; }
                if (d.fixTracking) { spend += this.FIXES.tracking.cost; sprints += this.FIXES.tracking.sprints; npsD += 4; matchD += 3; }
                if (d.fixQa) { spend += this.FIXES.qa.cost; sprints += this.FIXES.qa.sprints; npsD += 5; repeatD += 5; }
                if (d.fixPayouts) { spend += this.FIXES.payouts.cost; sprints += this.FIXES.payouts.sprints; supplyD += 9; matchD += 2; }
                if (d.fixResolution) { spend += this.FIXES.resolution.cost; sprints += this.FIXES.resolution.sprints; npsD += 3; repeatD += 3; supplyD += 2; }

                const supplyInPlan = (d.fixPayouts || d.fixOnboarding);
                const consumerHeavy = (d.fixBooking || d.fixQa) && !supplyInPlan;
                const reserveKept = (this.BUDGET_CAP - (ds.budgetUsed + spend)) >= 150; // ≥ ₹1.5 cr left

                if (d.fixPayouts && supplyInPlan && reserveKept) coachKey = `coach_r2_balanced`;
                else if (consumerHeavy) coachKey = `coach_r2_consumeronly`;
                else if (!reserveKept) coachKey = `coach_r2_noreserve`;
                else coachKey = `coach_r2_mixed`;

                summaryKey = (d.fixPayouts && reserveKept) ? `sum_r2_good` : (consumerHeavy ? `sum_r2_consumer` : `sum_r2_weak`);
            } else if (round === 3) {
                // Matching objective redistributes value among actors.
                switch (d.matching) {
                    case `fairness`: matchD += 4; supplyD += 8; npsD += 2; coachKey = `coach_r3_fairness`; break;
                    case `quality`: matchD += 2; npsD += 5; supplyD += 2; coachKey = `coach_r3_quality`; break;
                    case `speed`: matchD += 9; supplyD -= 8; npsD -= 2; coachKey = `coach_r3_speed`; break;
                    case `price`: matchD += 3; npsD -= 2; supplyD -= 4; coachKey = `coach_r3_price`; break;
                }
                // Trust architecture — target the risk, don't stack everything (trust theater).
                switch (d.trust) {
                    case `verification`: npsD += 5; supplyD += 2; coachKey = (d.matching === `fairness`) ? `coach_r3_targeted` : coachKey; break;
                    case `ratings`: npsD += 3; break;
                    case `escrow`: npsD += 2; repeatD -= 1; break;
                    case `insurance`: npsD += 2; break;
                    case `stackall`: npsD += 1; repeatD -= 6; coachKey = `coach_r3_theater`; break;
                }
                // Defend top-pro effective earnings vs UrbanReady's ₹45k.
                if (d.payfloor >= 60) { supplyD += 6; }
                else if (d.payfloor <= 25) { supplyD -= 5; coachKey = (d.trust !== `stackall`) ? `coach_r3_lowpay` : coachKey; }
                // Trust friction suppresses conversion (repeat usage) above 1 extra step.
                if (d.friction >= 3) { repeatD -= 5; npsD -= 2; }
                else if (d.friction === 0 && (d.trust === `verification`)) { npsD -= 2; }

                summaryKey = (d.matching === `fairness` && d.trust === `verification`) ? `sum_r3_good`
                    : (d.matching === `speed` ? `sum_r3_speed` : (d.trust === `stackall` ? `sum_r3_theater` : `sum_r3_weak`));
            } else if (round === 4) {
                // Rebalance for sustained two-sided health.
                const supplyWeak = ds.supply < ds.nps && ds.supply < ds.repeat;
                switch (d.rebalance) {
                    case `proearnings`: supplyD += 9; matchD += 2; coachKey = supplyWeak ? `coach_r4_proearnings_right` : `coach_r4_proearnings`; break;
                    case `consumertrust`: npsD += 5; supplyD -= 3; coachKey = supplyWeak ? `coach_r4_wrongside` : `coach_r4_consumertrust`; break;
                    case `pricewar`: supplyD += 4; npsD -= 2; repeatD -= 2; coachKey = `coach_r4_pricewar`; break;
                    case `nothing`: supplyD -= 4; npsD -= 2; coachKey = `coach_r4_nothing`; break;
                }
                // Service recovery and the recovery paradox.
                switch (d.recovery) {
                    case `fastvisible`: npsD += 7; repeatD += 6; supplyD += 1; coachKey = (d.rebalance === `proearnings`) ? `coach_r4_recover_right` : coachKey; break;
                    case `quiet`: npsD += 2; repeatD += 1; coachKey = (coachKey === `coach_default`) ? `coach_r4_quiet` : coachKey; break;
                    case `ignore`: npsD -= 8; repeatD -= 6; coachKey = `coach_r4_ignore`; break;
                }
                // Board pitch framing.
                switch (d.pitch) {
                    case `twosided`: npsD += 2; supplyD += 3; break;
                    case `consumeronly`: supplyD -= 2; coachKey = (coachKey === `coach_default` || coachKey === `coach_r4_quiet`) ? `coach_r4_consumeronly` : coachKey; break;
                    case `vanity`: matchD += 1; supplyD -= 4; npsD -= 2; coachKey = `coach_r4_vanity`; break;
                }
                // Conviction nudge.
                npsD += Math.round((d.conviction - 60) / 12);
                supplyD += Math.round((d.conviction - 60) / 14);

                summaryKey = (d.rebalance === `proearnings` && d.recovery === `fastvisible` && d.pitch === `twosided`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Resource accounting (only R2 spends/uses sprints) ----
            ds.budgetUsed = Math.min(this.BUDGET_CAP, ds.budgetUsed + spend);
            ds.sprintsUsed = Math.min(this.SPRINT_CAP, ds.sprintsUsed + sprints);

            // ---- Cross-side network effect: chronically weak supply drags match + repeat ----
            // A delighted consumer side cannot hold up if the supply base is collapsing.
            ds.nps = Math.max(0, Math.min(100, ds.nps + npsD));
            ds.supply = Math.max(0, Math.min(100, ds.supply + supplyD));
            let matchAfter = ds.match + matchD;
            let repeatAfter = ds.repeat + repeatD;
            if (ds.supply < 35) { matchAfter -= 4; repeatAfter -= 3; } // supply too thin to fill jobs well
            else if (ds.supply < 45) { matchAfter -= 2; repeatAfter -= 1; }
            ds.match = Math.max(0, Math.min(100, matchAfter));
            ds.repeat = Math.max(0, Math.min(100, repeatAfter));

            ds.npsHistory.push(Math.round(ds.nps));
            ds.matchHistory.push(Math.round(ds.match));
            ds.repeatHistory.push(Math.round(ds.repeat));
            ds.supplyHistory.push(Math.round(ds.supply));
            ds.performance = { overallScore: this._composite(ds) };

            if (ds.budgetUsed > this.BUDGET_CAP || ds.sprintsUsed > this.SPRINT_CAP) ds.overspent = true;

            const allTargets = ds.nps >= this.TARGET_NPS && ds.match >= this.TARGET_MATCH &&
                               ds.repeat >= this.TARGET_REPEAT && ds.supply >= this.TARGET_SUPPLY;
            if (round === this.ROUNDS.length && !allTargets) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                nps: Math.round(ds.nps),
                npsDelta: Math.round(npsD),
                match: Math.round(ds.match),
                matchDelta: Math.round(matchD),
                repeat: Math.round(ds.repeat),
                repeatDelta: Math.round(repeatD),
                supply: Math.round(ds.supply),
                supplyDelta: Math.round(supplyD),
                budgetUsed: ds.budgetUsed,
                sprintsUsed: ds.sprintsUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`npsDisplay`, `domainState.nps`, (v) => Math.round(Number(v)));
            uiManager.bind(`matchDisplay`, `domainState.match`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`repeatDisplay`, `domainState.repeat`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`supplyDisplay`, `domainState.supply`, (v) => {
                const card = document.querySelector(`.cxsim-card-supply`);
                if (card) card.classList.toggle(`cxsim-supply-healthy`, Number(v) >= this.TARGET_SUPPLY);
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.cxsim-budget-bar`);
                if (bar) bar.classList.toggle(`cxsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `₹` + (Number(v) / 100).toFixed(1) + ` / ₹9 crore`;
            });
            uiManager.bind(`sprintDisplay`, `domainState.sprintsUsed`, (v) => Math.round(Number(v)) + ` / 6 sprints`);

            const self = this;

            // Rigor slider readout.
            const rigor = document.getElementById(`rigorInput`);
            const rigorReadout = document.getElementById(`rigorReadout`);
            if (rigor && rigorReadout) {
                rigorReadout.textContent = rigor.value;
                rigor.addEventListener(`input`, function() { rigorReadout.textContent = rigor.value; });
            }
            // Payfloor slider readout.
            const pf = document.getElementById(`payfloorInput`);
            const pfReadout = document.getElementById(`payfloorReadout`);
            if (pf && pfReadout) {
                pfReadout.textContent = pf.value;
                pf.addEventListener(`input`, function() { pfReadout.textContent = pf.value; });
            }

            // Live portfolio spend + sprint readout.
            const fixIds = [
                [`fixBookingInput`, self.FIXES.booking],
                [`fixOnboardingInput`, self.FIXES.onboarding],
                [`fixTrackingInput`, self.FIXES.tracking],
                [`fixQaInput`, self.FIXES.qa],
                [`fixPayoutsInput`, self.FIXES.payouts],
                [`fixResolutionInput`, self.FIXES.resolution]
            ];
            const spendReadout = document.getElementById(`spendReadout`);
            const sprintLive = document.getElementById(`sprintLiveReadout`);
            const recompute = function() {
                let spend = 0, sprints = 0;
                fixIds.forEach((pair) => {
                    const el = document.getElementById(pair[0]);
                    if (el && parseInt(el.value, 10) === 1) { spend += pair[1].cost; sprints += pair[1].sprints; }
                });
                const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
                if (spendReadout) spendReadout.textContent = `₹` + (spend / 100).toFixed(1) + ` ` + t(`unit_crore`);
                if (sprintLive) sprintLive.textContent = sprints + ` ` + t(`unit_sprints`);
                const over = spend > self.BUDGET_CAP || sprints > self.SPRINT_CAP;
                if (spendReadout) spendReadout.style.color = over ? `#c0392b` : ``;
                if (sprintLive) sprintLive.style.color = over ? `#c0392b` : ``;
            };
            fixIds.forEach((pair) => {
                const el = document.getElementById(pair[0]);
                if (el) el.addEventListener(`change`, recompute);
            });
            recompute();
        }

        _composite(ds) {
            const nps = Math.round(ds.nps);
            const match = Math.round(ds.match);
            const repeat = Math.round(ds.repeat);
            const supply = Math.round(ds.supply);
            return Math.round(nps * 0.25 + match * 0.25 + repeat * 0.20 + supply * 0.30);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getChartConfig() {
            return {
                cxChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_nps`, `Consumer NPS`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_match`, `Match-Success %`),
                                data: [],
                                borderColor: `#14916e`,
                                backgroundColor: `rgba(20,145,110,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#14916e`,
