                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b07d16`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_supply`, `Supply Health`),
                                data: [],
                                borderColor: `#c0392b`,
                                backgroundColor: `rgba(192,57,43,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c0392b`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#1d2240`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#6c6a8f` }, grid: { color: `rgba(42,29,107,0.08)` },
                                title: { display: true, text: this._cl(`axis_score`, `0–100`), color: `#6c6a8f` }
                            },
                            x: {
                                ticks: { color: `#6c6a8f` }, grid: { color: `rgba(42,29,107,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#6c6a8f` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.npsHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                cxChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.npsHistory },
                        { data: ds.matchHistory },
                        { data: ds.repeatHistory },
                        { data: ds.supplyHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const nps = Math.round(ds.nps);
            const match = Math.round(ds.match);
            const repeat = Math.round(ds.repeat);
            const supply = Math.round(ds.supply);

            const hitAll = nps >= this.TARGET_NPS && match >= this.TARGET_MATCH &&
                           repeat >= this.TARGET_REPEAT && supply >= this.TARGET_SUPPLY;
            const consumerUp = nps >= this.TARGET_NPS && repeat >= this.TARGET_REPEAT;
            const supplyCollapsed = supply < 35;
            // Composite weights all four sides so a one-sided strategy cannot top-score.
            const composite = this._composite(ds);

            let performanceKey = `grade_slide`;
            if (hitAll && composite >= 72) performanceKey = `grade_twosided`;
            else if (hitAll) performanceKey = `grade_credible`;
            else if (consumerUp && supplyCollapsed) performanceKey = `grade_supplycrisis`;
            else if (consumerUp) performanceKey = `grade_onesided`;
            else if (composite >= 55) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitAll) insights.push(window.mySimulation.t(`insight_twosided`));
            else if (consumerUp && supplyCollapsed) insights.push(window.mySimulation.t(`insight_collapse`));
            else if (consumerUp) insights.push(window.mySimulation.t(`insight_onesided`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (supply < 45) insights.push(window.mySimulation.t(`insight_supply`));
            if (match < this.TARGET_MATCH) insights.push(window.mySimulation.t(`insight_match`));
            if (ds.overspent) insights.push(window.mySimulation.t(`insight_overspent`));
            if (hitAll && supply >= this.TARGET_SUPPLY + 10) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                nps: nps, match: match, repeat: repeat, supply: supply,
                hitAll: hitAll, composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: hitAll,
                supplyCollapsed: supplyCollapsed,
                overspent: ds.overspent,
                budgetUsed: ds.budgetUsed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="cxsim-cm-badge cxsim-cm-yes">` + T(`cm_twosided`) + `</span>`
                : `<span class="cxsim-cm-badge cxsim-cm-no">` + T(`cm_nottwosided`) + `</span>`;
            let failBadges = ``;
            if (s.supplyCollapsed) failBadges += ` <span class="cxsim-cm-badge cxsim-cm-fail">` + T(`cm_supplycrisis`) + `</span>`;
            if (s.overspent) failBadges += ` <span class="cxsim-cm-badge cxsim-cm-fail">` + T(`cm_overspent`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="cxsim-cm-metric"><span class="cxsim-cm-mv">` + Math.round(s.nps || 0) + `</span><span class="cxsim-cm-ml">` + T(`cm_m_nps`) + `</span></div>`
                + `<div class="cxsim-cm-metric"><span class="cxsim-cm-mv">` + Math.round(s.match || 0) + `%</span><span class="cxsim-cm-ml">` + T(`cm_m_match`) + `</span></div>`
                + `<div class="cxsim-cm-metric"><span class="cxsim-cm-mv">` + Math.round(s.repeat || 0) + `%</span><span class="cxsim-cm-ml">` + T(`cm_m_repeat`) + `</span></div>`
                + `<div class="cxsim-cm-metric"><span class="cxsim-cm-mv">` + Math.round(s.supply || 0) + `</span><span class="cxsim-cm-ml">` + T(`cm_m_supply`) + `</span></div>`;
            return ``
                + `<div class="cxsim-completion">`
                +   `<div class="cxsim-cm-head">`
                +     `<div class="cxsim-cm-score">` + score + `<span class="cxsim-cm-score-max">/100</span></div>`
                +     `<div class="cxsim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="cxsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="cxsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="cxsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.supply < 32) return window.mySimulation.t(`hint_supply`);
            if (ds.overspent) return window.mySimulation.t(`hint_overspent`);
            if (state.currentPeriod >= 3 && ds.match < 78) return window.mySimulation.t(`hint_match`);
            if (state.currentPeriod >= 2 && ds.nps < this.START_NPS) return window.mySimulation.t(`hint_nps`);
            if (ds.nps >= this.TARGET_NPS && ds.match >= this.TARGET_MATCH &&
                ds.repeat >= this.TARGET_REPEAT && ds.supply >= this.TARGET_SUPPLY) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.nps`, label: `NPS`, i18nKey: `col_nps`, formatter: (v) => Math.round(v) },
                { key: `results.match`, label: `Match`, i18nKey: `col_match`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.repeat`, label: `Repeat`, i18nKey: `col_repeat`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.supply`, label: `Supply`, i18nKey: `col_supply`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Experience by Design`,
                    subtitle:               `GharSe connects 1.9M households with 48,000 home-service professionals across six cities. In one quarter NPS fell 46 → 31, match-success 88% → 79%, repeat-usage 62% → 54%, and your best professionals are leaving twice as fast while UrbanReady dangles ₹45,000 guarantees. You have one quarter, ₹9 crore and 6 sprints to rebuild a two-sided experience — without delighting one side at the other's expense.`,
                    header_tag:             `April 2026 · GharSe · Bengaluru · 90 days to reverse the slide before the board cuts the budget`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `Two-Sided Health Trajectory`,
                    coach_header:           `Facilitator (Board sponsor & Head of Marketplace)`,
                    coach_intro:            `On a marketplace, experience isn't delivered to a customer — it's co-created among consumers, professionals and your matching infrastructure. A fix that delights consumers but bleeds your best pros shrinks supply, which craters match quality, which eventually hurts the consumers you just delighted. Diagnose the leak that is uniquely yours, protect both sides, engineer trust against the specific risk that broke it, and keep something in reserve to rebalance when one side responds.`,

                    nps_label:              `Consumer NPS`,
                    nps_sub:                `Was 46 · must trend up by day 90`,
                    match_label:            `Match-Success Rate`,
                    match_sub:              `Was 88% · filled within window`,
                    repeat_label:           `Repeat-Usage Rate`,
                    repeat_sub:             `Was 62% · rebook within 90 days`,
                    supply_label:           `Supply Health`,
                    supply_sub:             `Top-pro retention · churn doubled to 8%`,
                    budget_label:           `Improvement budget committed`,
                    sprint_label:           `Engineering sprints used`,

                    unit_crore:             `cr`,
                    unit_sprints:           `sprints`,
                    chart_start:            `Start`,

                    clock_r1:               `90-day board gate · diagnose the two-sided leak`,
                    clock_r2:               `₹9 crore · 6 sprints to allocate`,
